import java.nio.file.*;import javax.tools.ToolProvider;import java.net.*;import java.util.*;
class RoiProbe {
 public static void main(String[] args)throws Exception{Path out=Files.createTempDirectory("pis-t32-classes-");if(ToolProvider.getSystemJavaCompiler().run(null,null,null,"-d",out.toString(),"backend/src/main/java/com/pis/roi/RoiGeometry.java")!=0)throw new AssertionError("compile");try(var loader=new URLClassLoader(new URL[]{out.toUri().toURL()})){var type=loader.loadClass("com.pis.roi.RoiGeometry");var p=loader.loadClass("com.pis.roi.RoiGeometry$Point").getConstructor(double.class,double.class);var points=List.of(p.newInstance(0.,0.),p.newInstance(10.,20.));var valid=type.getMethod("validate",String.class,List.class,int.class,int.class);valid.invoke(null,"RECTANGLE",points,512,384);var measure=type.getMethod("measure",String.class,List.class,Double.class,Double.class,Long.class);var value=measure.invoke(null,"RECTANGLE",points,.5,2.,7L);if(!value.getClass().getMethod("length").invoke(value).equals(90.0))throw new AssertionError("anisotropic");var raw=measure.invoke(null,"RECTANGLE",points,null,null,null);if(!raw.getClass().getMethod("unit").invoke(raw).equals("px"))throw new AssertionError("unknown calibration");for(double x:new double[]{Double.NaN,Double.POSITIVE_INFINITY,-1,513}){try{valid.invoke(null,"POINT",List.of(p.newInstance(x,0.)),512,384);throw new AssertionError("accepted invalid");}catch(java.lang.reflect.InvocationTargetException e){if(!(e.getCause() instanceof IllegalArgumentException))throw e;}}try{valid.invoke(null,"POLYGON",List.of(p.newInstance(0.,0.),p.newInstance(10.,10.),p.newInstance(0.,10.),p.newInstance(10.,0.)),512,384);throw new AssertionError("crossing");}catch(java.lang.reflect.InvocationTargetException e){if(!(e.getCause() instanceof IllegalArgumentException))throw e;}}System.out.println("PASS actual JDK ROI geometry: finite/bounds/self-intersection and versioned anisotropic measurement");}
}
